-- Generated by Supabase CLI: additive editing of existing categories/options.
-- Stable IDs, SKUs, group links, price authority and paid history are retained.
begin;
set local lock_timeout='5s';
set local statement_timeout='30s';
set local check_function_bodies=on;

do $profile$
begin
  if to_regnamespace('dishbee_private') is not null
    or to_regclass('mealdeck_private.installation') is null then
    raise exception 'mealdeck_menu_structure_independent_profile_required'; end if;
  if current_user in ('anon','authenticated','service_role') or not exists(
    select 1 from pg_class c where c.oid='mealdeck_private.installation'::regclass
      and pg_has_role(current_user,c.relowner,'USAGE')) then
    raise exception 'mealdeck_menu_structure_database_owner_required'; end if;
  if not exists(select 1 from mealdeck_private.installation where singleton
      and profile='mealdeck-independent-v1' and business_id is not null)
    or to_regprocedure('public.mealdeck_ops_modifier_prices(uuid)') is null
    or to_regprocedure('public.mealdeck_public_launch_catalogue(uuid,uuid,text[],uuid[])') is null then
    raise exception 'mealdeck_menu_structure_previous_extensions_required'; end if;
end $profile$;

create or replace function mealdeck_ops_private.assert_menu_structure_permission(
  p_tenant uuid,p_permission text
) returns void language plpgsql stable security definer set search_path='' as $$
begin
  if p_permission is null or p_permission not in ('menu.read','menu.write')
    or auth.uid() is null or not mealdeck_ops_private.can(p_tenant,null,p_permission)
    or not exists(select 1 from mealdeck_private.installation where singleton
      and profile='mealdeck-independent-v1' and business_id=p_tenant) then
    raise exception 'mealdeck_ops_forbidden' using errcode='42501'; end if;
end $$;
revoke all on function mealdeck_ops_private.assert_menu_structure_permission(uuid,text)
  from public,anon,authenticated,service_role;

create or replace function public.mealdeck_ops_menu_categories(p_tenant uuid)
returns table(category_id uuid,brand_id uuid,brand_name text,category_name text,
  active boolean,affected_item_count integer)
language plpgsql stable security definer set search_path='' as $$
begin
  perform mealdeck_ops_private.assert_menu_structure_permission(p_tenant,'menu.read');
  return query select c.id,c.brand_id,b.name::text,c.name::text,c.active,
    (select count(*)::integer from public.menu_items i where i.tenant_id=p_tenant
      and i.category_id=c.id and i.brand_id=c.brand_id)
    from public.menu_categories c join public.tenant_brands b
      on b.tenant_id=c.tenant_id and b.id=c.brand_id
    where c.tenant_id=p_tenant order by b.name,c.sort_order,c.name,c.id;
end $$;

create or replace function public.mealdeck_ops_update_menu_category(
  p_tenant uuid,p_category uuid,p_brand uuid,p_name text,p_active boolean,
  p_expected_name text,p_expected_active boolean
) returns jsonb language plpgsql security definer set search_path='' as $$
declare previous public.menu_categories%rowtype;v_name text:=btrim(p_name);
  brand_name text;affected integer;changed boolean;
begin
  perform mealdeck_ops_private.assert_menu_structure_permission(p_tenant,'menu.write');
  if p_name is null or length(v_name) not between 2 and 140 or p_name~'[[:cntrl:]]'
    or p_active is null or p_expected_name is null or p_expected_active is null then
    raise exception 'mealdeck_ops_category_invalid'; end if;
  select * into previous from public.menu_categories c
    where c.tenant_id=p_tenant and c.id=p_category and c.brand_id=p_brand for update;
  if not found then raise exception 'mealdeck_ops_category_not_found'; end if;
  -- Recheck permissions after waiting for another editor's row lock.
  perform mealdeck_ops_private.assert_menu_structure_permission(p_tenant,'menu.write');
  if previous.name is distinct from p_expected_name or previous.active is distinct from p_expected_active then
    raise exception 'mealdeck_ops_category_conflict'; end if;
  select b.name into brand_name from public.tenant_brands b where b.tenant_id=p_tenant and b.id=p_brand;
  select count(*)::integer into affected from public.menu_items i where i.tenant_id=p_tenant
    and i.category_id=p_category and i.brand_id=p_brand;
  changed:=previous.name<>v_name or previous.active<>p_active;
  if changed then
    update public.menu_categories c set name=v_name,active=p_active
      where c.tenant_id=p_tenant and c.id=p_category and c.brand_id=p_brand;
    insert into public.mealdeck_ops_audit_log(tenant_id,location_id,actor_id,action,entity_type,entity_id,previous_value,next_value)
      values(p_tenant,null,auth.uid(),'menu.category.update','menu_category',p_category,
        jsonb_build_object('brandId',p_brand,'name',previous.name,'active',previous.active),
        jsonb_build_object('brandId',p_brand,'name',v_name,'active',p_active,'affectedItemCount',affected));
  end if;
  return jsonb_build_object('category_id',p_category,'brand_id',p_brand,'brand_name',brand_name,
    'category_name',v_name,'active',p_active,'affected_item_count',affected,'changed',changed);
end $$;

create or replace function public.mealdeck_ops_modifier_update_option(
  p_tenant uuid,p_option uuid,p_group uuid,p_name text,p_price_pence integer,p_active boolean,
  p_expected_name text,p_expected_price_pence integer,p_expected_active boolean
) returns jsonb language plpgsql security definer set search_path='' as $$
declare previous public.modifier_options%rowtype;v_name text:=btrim(p_name);
  group_name text;affected integer;changed boolean;
begin
  perform mealdeck_ops_private.assert_menu_structure_permission(p_tenant,'menu.write');
  if p_name is null or length(v_name) not between 1 and 140 or p_name~'[[:cntrl:]]'
    or p_price_pence is null or p_price_pence not between 0 and 1000000
    or p_active is null or p_expected_name is null or p_expected_price_pence is null
    or p_expected_active is null then raise exception 'mealdeck_ops_modifier_option_invalid'; end if;
  select * into previous from public.modifier_options o
    where o.tenant_id=p_tenant and o.id=p_option and o.group_id=p_group for update;
  if not found then raise exception 'mealdeck_ops_modifier_not_found'; end if;
  perform mealdeck_ops_private.assert_menu_structure_permission(p_tenant,'menu.write');
  if previous.name is distinct from p_expected_name
    or previous.price_delta_pence is distinct from p_expected_price_pence
    or previous.active is distinct from p_expected_active then
    raise exception 'mealdeck_ops_modifier_option_conflict'; end if;
  select g.name into group_name from public.modifier_groups g where g.tenant_id=p_tenant and g.id=p_group;
  select count(*)::integer into affected from public.menu_item_modifier_groups link
    join public.menu_items i on i.tenant_id=link.tenant_id and i.id=link.item_id
    where link.tenant_id=p_tenant and link.group_id=p_group;
  changed:=previous.name<>v_name or previous.price_delta_pence<>p_price_pence or previous.active<>p_active;
  if changed then
    update public.modifier_options o set name=v_name,
      price_delta_pence=p_price_pence,active=p_active
      where o.tenant_id=p_tenant and o.id=p_option and o.group_id=p_group;
    insert into public.mealdeck_ops_audit_log(tenant_id,location_id,actor_id,action,entity_type,entity_id,previous_value,next_value)
      values(p_tenant,null,auth.uid(),'menu.modifier_option.update','modifier_option',p_option,
        jsonb_build_object('groupId',p_group,'name',previous.name,'pricePence',previous.price_delta_pence,'active',previous.active),
        jsonb_build_object('groupId',p_group,'name',v_name,'pricePence',p_price_pence,'active',p_active,'affectedItemCount',affected));
  end if;
  return jsonb_build_object('option_id',p_option,'group_id',p_group,'group_name',group_name,
    'option_name',v_name,'price_delta_pence',p_price_pence,'active',p_active,
    'affected_item_count',affected,'changed',changed);
end $$;

revoke all on function public.mealdeck_ops_menu_categories(uuid),
  public.mealdeck_ops_update_menu_category(uuid,uuid,uuid,text,boolean,text,boolean),
  public.mealdeck_ops_modifier_update_option(uuid,uuid,uuid,text,integer,boolean,text,integer,boolean)
  from public,anon,authenticated,service_role;
grant execute on function public.mealdeck_ops_menu_categories(uuid),
  public.mealdeck_ops_update_menu_category(uuid,uuid,uuid,text,boolean,text,boolean),
  public.mealdeck_ops_modifier_update_option(uuid,uuid,uuid,text,integer,boolean,text,integer,boolean)
  to authenticated;

-- Public presentation receives only the already reviewed SKU/option rows, with
-- editable labels added. Existing publication and scope filters stay intact.

create or replace function public.mealdeck_public_launch_catalogue(
  p_tenant uuid,p_location uuid,p_skus text[],p_replacement_options uuid[]
) returns jsonb language plpgsql stable security definer set search_path='' as $function$
declare items jsonb; replacements jsonb;
begin
  -- ACLs below admit only service_role. No customer identity or caller-selected
  -- kitchen can override the installed business and sole active launch kitchen.
  if p_tenant is null or p_location is null
    or not exists(select 1 from mealdeck_private.installation i
      join public.tenants t on t.id=i.business_id
      join public.tenant_locations l on l.tenant_id=t.id
      where i.singleton and i.profile='mealdeck-independent-v1'
        and i.business_id=p_tenant and i.bootstrap_owner_id is not null
        and i.bootstrapped_at is not null and t.active
        and t.slug='mealdeck' and t.legal_name='313 Brands Ltd' and t.currency='GBP'
        and l.id=p_location and l.slug='shared-kitchen' and l.active)
    or (select count(*) from public.tenants)<>1
    or (select count(*) from public.tenant_locations where tenant_id=p_tenant and active)<>1 then
    raise exception 'mealdeck_public_menu_scope_unavailable';
  end if;
  if p_skus is null or cardinality(p_skus) not between 1 and 256
    or exists(select 1 from unnest(p_skus) s where s is null or length(s)>180
      or s !~ '^[a-z0-9]+(-[a-z0-9]+)*$')
    or (select count(distinct s) from unnest(p_skus) s)<>cardinality(p_skus)
    or p_replacement_options is null or cardinality(p_replacement_options)>128
    or exists(select 1 from unnest(p_replacement_options) o where o is null)
    or (select count(distinct o) from unnest(p_replacement_options) o)<>cardinality(p_replacement_options) then
    raise exception 'mealdeck_public_menu_invalid_request';
  end if;

  -- Publication and routing match price_checkout_lines. The channel's enabled
  -- switch, opening hours and payment setup intentionally do not gate browsing.
  select coalesce(jsonb_agg(jsonb_build_object(
    'sku',x.sku,'brandSlug',b.slug,'categoryName',c.name,'name',x.name,'description',nullif(x.description,''),
    'pricePence',coalesce(r.price_override_pence,x.price_pence),
    'requiredGroupIds',coalesce((select jsonb_agg(g.id order by g.id)
      from public.menu_item_modifier_groups a
      join public.modifier_groups g on g.id=a.group_id and g.tenant_id=a.tenant_id
      where a.tenant_id=p_tenant and a.item_id=x.id and g.min_select>0),'[]'::jsonb),
    'options',coalesce((select jsonb_agg(jsonb_build_object(
        'id',o.id,'groupId',o.group_id,'label',o.name,'pricePence',o.price_delta_pence,'available',o.active
      ) order by o.id)
      from public.menu_item_modifier_groups a
      join public.modifier_groups g on g.id=a.group_id and g.tenant_id=a.tenant_id
      join public.modifier_options o on o.group_id=g.id and o.tenant_id=g.tenant_id
      where a.tenant_id=p_tenant and a.item_id=x.id),'[]'::jsonb)
  ) order by x.sku),'[]'::jsonb) into items
  from public.menu_items x
  join public.tenant_brands b on b.id=x.brand_id and b.tenant_id=x.tenant_id
  join public.menu_categories c on c.id=x.category_id and c.tenant_id=x.tenant_id and c.brand_id=x.brand_id
  join public.menu_item_channel_rules r on r.menu_item_id=x.id and r.tenant_id=x.tenant_id
    and r.location_id=p_location and r.channel_key='mealdeck'
  where x.tenant_id=p_tenant and x.sku=any(p_skus) and x.active and b.active and c.active and r.visible
    and b.slug in ('skorch-burgers','loadd','moktl','tavo-chicken','souvano')
    and (select count(*) from public.menu_items duplicate where duplicate.tenant_id=p_tenant and duplicate.sku=x.sku)=1
    and exists(select 1 from public.menu_item_station_routes route
      join public.kitchen_stations station on station.id=route.station_id
        and station.tenant_id=route.tenant_id and station.location_id=route.location_id and station.active
      where route.tenant_id=p_tenant and route.location_id=p_location and route.item_id=x.id);

  -- Cross replacements are not linked to every source main: their canonical
  -- option is charged instead of the selected source upgrade, exactly once.
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',o.id,'groupId',o.group_id,'label',o.name,'pricePence',o.price_delta_pence,'available',o.active
  ) order by o.id),'[]'::jsonb) into replacements
  from public.modifier_options o
  join public.modifier_groups g on g.id=o.group_id and g.tenant_id=o.tenant_id
  where o.tenant_id=p_tenant and o.id=any(p_replacement_options);

  return jsonb_build_object('schemaVersion',1,'tenantId',p_tenant,'locationId',p_location,
    'checkedAt',now(),'items',items,'replacementOptions',replacements);
end
$function$;
revoke all on function public.mealdeck_public_launch_catalogue(uuid,uuid,text[],uuid[])
  from public,anon,authenticated,service_role;
grant execute on function public.mealdeck_public_launch_catalogue(uuid,uuid,text[],uuid[]) to service_role;
comment on function public.mealdeck_public_launch_catalogue(uuid,uuid,text[],uuid[]) is
  'Read-only launch catalogue for the MealDeck server adapter. Service role only; no checkout or publication side effects.';
commit;
